/**
 * The story 12 image fixtures, as files a test can hand to a browser or to the model.
 *
 * Everything here is a real file in `tests/fixtures/images/`, generated by
 * `scripts/make-image-fixtures.mjs` — real because this story's rules are decided by file
 * *content*: a sniffer, a size limit and a browser's image decoder all ignore what a file is
 * called, so a fixture that only looks like an image would test the wrong thing.
 *
 * The two files on either side of the size limit are the exception: an eleven-megabyte
 * fixture does not belong in a repository, so `paddedJpeg` builds them at run time from
 * `photo-small.jpg`. Anything after a JPEG's end-of-image marker is ignored by every decoder
 * we test, which makes an exact byte length possible without faking the format.
 */
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const IMAGES_DIR = join(dirname(fileURLToPath(import.meta.url)), 'images');

/** The MIME type each fixture's bytes really are. */
const MIME_TYPES: Record<string, string> = {
  png: 'image/png',
  jpg: 'image/jpeg',
  gif: 'image/gif',
  webp: 'image/webp',
  svg: 'image/svg+xml',
};

/** A file a test can upload, drop or pick: a name, the type to claim, and the bytes. */
export interface ImageFixture {
  name: string;
  mimeType: string;
  bytes: Uint8Array<ArrayBuffer>;
}

/**
 * The bytes of one fixture file.
 *
 * Copied out of the `Buffer`, which is a view on a shared pool: the typed `BlobPart` and
 * `BodyInit` only take a view on the buffer it owns, and a fixture is always handed to one.
 */
export function fixtureBytes(name: string): Uint8Array<ArrayBuffer> {
  return new Uint8Array(readFileSync(join(IMAGES_DIR, name)));
}

/** The MIME type implied by a fixture's extension. */
export function fixtureMime(name: string): string {
  const extension = name.split('.').pop() ?? '';
  return MIME_TYPES[extension] ?? 'application/octet-stream';
}

/**
 * One fixture as a `File`.
 *
 * `as` renames it, which is the whole point of `renamed-pdf.png`-style cases: the name says
 * one thing and the bytes say another, and both the browser's check and the Worker's have to
 * go by the bytes.
 */
export function fixtureFile(name: string, as?: string): File {
  const target = as ?? name;
  return new File([fixtureBytes(name)], target, { type: fixtureMime(target) });
}

/**
 * `photo-small.jpg` padded to exactly `bytes`.
 *
 * The padding sits after the end-of-image marker, so the file stays a decodable JPEG whose
 * only unusual property is its length — the boundary `image.size_limit` is written against.
 */
export function paddedJpegFile(name: string, bytes: number): File {
  const base = fixtureBytes('photo-small.jpg');
  if (bytes < base.length) throw new Error(`${name}: cannot pad to ${bytes}, the fixture is already longer`);
  const padded = new Uint8Array(bytes);
  padded.set(base, 0);
  // 0x20 padding: a decoder stops at the marker before it, and a length check sees the total.
  padded.fill(0x20, base.length);
  return new File([padded], name, { type: 'image/jpeg' });
}

/** A file whose bytes are a PNG but whose name, and claimed type, are something else. */
export function fileNamed(name: string, bytes: Uint8Array<ArrayBuffer>, mimeType: string): File {
  return new File([bytes], name, { type: mimeType });
}
